CREATE TABLE `t_perm_dept` (
  `id` varchar(36) NOT NULL COMMENT '主键UUID',
  `create_time` datetime NOT NULL COMMENT '创建时间',
  `create_by` varchar(36) DEFAULT NULL COMMENT '创建人ID',
  `update_time` datetime DEFAULT NULL COMMENT '修改时间',
  `update_by` varchar(36) DEFAULT NULL COMMENT '修改人ID',
  `is_deleted` tinyint(1) NOT NULL DEFAULT '0' COMMENT '逻辑删除',
  `dept_name` varchar(50) NOT NULL COMMENT '部门名称',
  `dept_short` varchar(20) DEFAULT NULL COMMENT '部门简称（表格窄列展示）',
  `parent_id` varchar(36) DEFAULT NULL COMMENT '上级部门ID，校级为NULL',
  `dept_level` int NOT NULL DEFAULT '2' COMMENT '部门层级 1校级 2部门 3学段',
  `sort_no` int NOT NULL DEFAULT '0' COMMENT '排序号',
