  PRIMARY KEY (`id`),
  KEY `idx_dept_parent` (`parent_id`),
  KEY `idx_dept_level` (`dept_level`),
  KEY `idx_dept_name` (`dept_name`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='权限-部门表';
