CREATE TABLE `t_perm_log` (
  `id` varchar(36) NOT NULL COMMENT '主键UUID',
  `create_time` datetime NOT NULL COMMENT '创建时间',
  `create_by` varchar(36) DEFAULT NULL COMMENT '创建人ID',
  `update_time` datetime DEFAULT NULL COMMENT '修改时间',
  `update_by` varchar(36) DEFAULT NULL COMMENT '修改人ID',
  `is_deleted` tinyint(1) NOT NULL DEFAULT '0' COMMENT '逻辑删除',
  `log_time` datetime NOT NULL COMMENT '操作时间',
  `operator_id` varchar(36) DEFAULT NULL COMMENT '操作人ID',
  `operator_name` varchar(50) NOT NULL COMMENT '操作人姓名',
  `operator_role` varchar(50) DEFAULT NULL COMMENT '操作人角色',
  `module_name` varchar(32) NOT NULL COMMENT '所属模块 市场咨询/教学部门/实训-教学/就业管理/教务部门/财务管理/审批中心/权限管理',
  `action_type` varchar(20) NOT NULL COMMENT '操作类型 登录/新增/修改/删除/审批/导出/权限变更',
  `target_obj` varchar(128) DEFAULT NULL COMMENT '操作对象',
  `before_value` varchar(1000) DEFAULT NULL,
  `after_value` varchar(1000) DEFAULT NULL,
  `ip` varchar(64) DEFAULT NULL COMMENT '来源IP',
  `result` varchar(10) NOT NULL DEFAULT '成功' COMMENT '结果 成功/失败',
  `api_path` varchar(255) DEFAULT NULL COMMENT '访问的接口路径',
  `http_method` varchar(10) DEFAULT NULL COMMENT 'HTTP 方法',
  `status_code` int DEFAULT NULL COMMENT 'HTTP 状态码',
  `duration_ms` int DEFAULT NULL COMMENT '处理耗时（毫秒）',
  `user_agent` varchar(255) DEFAULT NULL COMMENT '设备 / 浏览器',
  PRIMARY KEY (`id`),
  KEY `idx_log_time` (`log_time`),
  KEY `idx_log_module` (`module_name`),
  KEY `idx_log_action` (`action_type`),
  KEY `idx_log_operator` (`operator_name`),
  KEY `idx_log_result` (`result`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='权限-操作日志表';
/*!40101 SET character_set_client = @saved_cs_client */;
