CREATE TABLE `t_perm_menu` (
  `id` varchar(36) NOT NULL COMMENT '主键UUID',
  `create_time` datetime NOT NULL COMMENT '创建时间',
  `create_by` varchar(36) DEFAULT NULL COMMENT '创建人ID',
  `update_time` datetime DEFAULT NULL COMMENT '修改时间',
  `update_by` varchar(36) DEFAULT NULL COMMENT '修改人ID',
  `is_deleted` tinyint(1) NOT NULL DEFAULT '0' COMMENT '逻辑删除',
  `module_key` varchar(32) NOT NULL COMMENT '模块key market/teach/train/job/acad/fin/approve/perm',
  `module_name` varchar(32) NOT NULL COMMENT '模块名称',
  `module_icon` varchar(16) DEFAULT NULL COMMENT '模块图标 emoji',
  `module_sort` int NOT NULL DEFAULT '0' COMMENT '模块排序',
  `item_name` varchar(64) NOT NULL COMMENT '功能点名称',
  `parent_item_name` varchar(64) DEFAULT NULL COMMENT '父功能点名称（二级功能点用）',
  `item_sort` int NOT NULL DEFAULT '0' COMMENT '功能点排序',
  `remark` varchar(255) DEFAULT NULL COMMENT '备注',
  `is_custom` tinyint(1) NOT NULL DEFAULT '0' COMMENT '1=用户自建权限点（可改可删）',
  PRIMARY KEY (`id`),
  KEY `idx_menu_module` (`module_key`),
  KEY `idx_menu_module_item` (`module_key`,`item_name`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='权限-功能点表';
