CREATE TABLE `t_perm_role_perm` (
  `id` varchar(36) NOT NULL COMMENT '主键UUID',
  `create_time` datetime NOT NULL COMMENT '创建时间',
  `create_by` varchar(36) DEFAULT NULL COMMENT '创建人ID',
  `update_time` datetime DEFAULT NULL COMMENT '修改时间',
  `update_by` varchar(36) DEFAULT NULL COMMENT '修改人ID',
  `is_deleted` tinyint(1) NOT NULL DEFAULT '0' COMMENT '逻辑删除',
  `role_id` varchar(36) NOT NULL COMMENT '角色ID',
  `menu_id` varchar(36) NOT NULL COMMENT '功能点ID',
  `module_key` varchar(32) NOT NULL COMMENT '模块key（冗余，便于按模块统计）',
  `item_name` varchar(64) NOT NULL COMMENT '功能点名称（冗余，便于联表展示）',
  `action_code` varchar(64) NOT NULL COMMENT '动作编码',
  `action_name` varchar(64) NOT NULL COMMENT '动作中文名',
  `base_action` int NOT NULL COMMENT '动作基类 1-6',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_role_menu_action` (`role_id`,`menu_id`,`action_code`),
  KEY `idx_rp_role` (`role_id`),
  KEY `idx_rp_role_menu` (`role_id`,`menu_id`),
  KEY `idx_rp_module` (`module_key`)
