CREATE TABLE `t_perm_rule` (
  `id` varchar(36) NOT NULL COMMENT '主键UUID',
  `create_time` datetime NOT NULL COMMENT '创建时间',
  `create_by` varchar(36) DEFAULT NULL COMMENT '创建人ID',
  `update_time` datetime DEFAULT NULL COMMENT '修改时间',
  `update_by` varchar(36) DEFAULT NULL COMMENT '修改人ID',
  `is_deleted` tinyint(1) NOT NULL DEFAULT '0' COMMENT '逻辑删除',
  `rule_group` varchar(20) NOT NULL COMMENT '规则分组 pwd/login/approval',
  `rule_key` varchar(32) NOT NULL COMMENT '规则键',
  `rule_value` varchar(255) NOT NULL COMMENT '规则值（字符串形式存储）',
  `rule_sort` int NOT NULL DEFAULT '0' COMMENT '排序号',
  `remark` varchar(255) DEFAULT NULL COMMENT '说明',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_rule_group_key` (`rule_group`,`rule_key`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='权限-规则配置表';
