CREATE TABLE `t_perm_user` (
  `id` varchar(36) NOT NULL COMMENT '主键UUID',
  `create_time` datetime NOT NULL COMMENT '创建时间',
  `create_by` varchar(36) DEFAULT NULL COMMENT '创建人ID',
  `update_time` datetime DEFAULT NULL COMMENT '修改时间',
  `update_by` varchar(36) DEFAULT NULL COMMENT '修改人ID',
  `is_deleted` tinyint(1) NOT NULL DEFAULT '0' COMMENT '逻辑删除',
  `user_name` varchar(50) NOT NULL COMMENT '姓名，仅汉字且不低于2位',
  `gw_no` varchar(20) NOT NULL COMMENT '工号，格式 GW+4位数字',
  `account` varchar(50) NOT NULL COMMENT '登录账号，字母/数字，4-20位',
  `phone` varchar(20) NOT NULL COMMENT '手机号，11位以1开头',
  `gender` int NOT NULL COMMENT '性别 1男 2女',
  `age` int DEFAULT NULL COMMENT '年龄',
  `dept_id` varchar(36) DEFAULT NULL COMMENT '所属部门ID',
  `password` varchar(128) NOT NULL COMMENT '密码（演示用明文，接入登录模块后改哈希）',
  `pwd_algo` varchar(20) NOT NULL DEFAULT 'plain' COMMENT '密码算法 plain/bcrypt',
  `user_status` varchar(10) NOT NULL DEFAULT '正常' COMMENT '账号状态 正常/已停用（锁定档已于 2026-10-25 移除）',
  `need_change_pwd` tinyint(1) NOT NULL DEFAULT '0' COMMENT '是否待改初始密码',
  `pwd_error_count` int NOT NULL DEFAULT '0' COMMENT '连续密码错误次数（登录模块维护）',
  `last_login_time` datetime DEFAULT NULL COMMENT '最近登录时间',
  `remark` varchar(255) DEFAULT NULL COMMENT '备注',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_user_gw` (`gw_no`),
  UNIQUE KEY `uk_user_account` (`account`),
  UNIQUE KEY `uk_user_phone` (`phone`),
  KEY `idx_user_dept` (`dept_id`),
  KEY `idx_user_status` (`user_status`),
  KEY `idx_user_need_change` (`need_change_pwd`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='权限-账号表';
/*!40101 SET character_set_client = @saved_cs_client */;
